public class ConfiguredModelAlgorithmFactory(string resourceName = null, Action<Humidifier.CleanRoomsML.ConfiguredModelAlgorithm> factoryAction = null) : ResourceFactory<Humidifier.CleanRoomsML.ConfiguredModelAlgorithm>(resourceName)
{

    internal InnerConfiguredModelAlgorithmInferenceContainerConfigFactory InferenceContainerConfigFactory { get; set; }

    internal InnerConfiguredModelAlgorithmContainerConfigFactory TrainingContainerConfigFactory { get; set; }

    protected override Humidifier.CleanRoomsML.ConfiguredModelAlgorithm Create()
    {
        var configuredModelAlgorithmResult = CreateConfiguredModelAlgorithm();
        factoryAction?.Invoke(configuredModelAlgorithmResult);

        return configuredModelAlgorithmResult;
    }

    private Humidifier.CleanRoomsML.ConfiguredModelAlgorithm CreateConfiguredModelAlgorithm()
    {
        var configuredModelAlgorithmResult = new Humidifier.CleanRoomsML.ConfiguredModelAlgorithm
        {
            GivenName = InputResourceName,
        };

        return configuredModelAlgorithmResult;
    }
    public override void CreateChildren(Humidifier.CleanRoomsML.ConfiguredModelAlgorithm result)
    {
        base.CreateChildren(result);

        result.InferenceContainerConfig ??= InferenceContainerConfigFactory?.Build();
        result.TrainingContainerConfig ??= TrainingContainerConfigFactory?.Build();
    }

} // End Of Class

